import { rpc } from "./request.js";

// Navigate only to a live group member's canonical unicast IPv4 address.
export function masterDashboardUrl(status, hostname) {
	if (status?.master !== false || status.settled !== true || status.electionPending === true ||
		!/^[0-9a-f]{12}$/i.test(status.masterId || "") || status.masterId === status.localId || !Array.isArray(status.devices)) return "";
	const peer = status.devices.find((device) => device?.id === status.masterId && device.online === true);
	const ip = status.masterIp;
	if (!peer || peer.ip !== ip || typeof ip !== "string") return "";
	const parts = ip.split(".");
	if (parts.length !== 4 || !parts.every((part) => /^(0|[1-9]\d{0,2})$/.test(part) && Number(part) <= 255)) return "";
	if (Number(parts[0]) === 0 || Number(parts[0]) === 127 || Number(parts[0]) >= 224 || ip === hostname) return "";
	return "http://" + ip + "/";
}

// Confirm that the destination still leads before replacing browser history; stale elections cannot bounce pages.
export async function redirectToMaster(status, location, request = rpc) {
	const target = masterDashboardUrl(status, location.hostname);
	if (!target) return false;
	const controller = new AbortController();
	const timeout = setTimeout(() => controller.abort(), 3000);
	try {
		const destination = await request(target.slice(0, -1), { op: "status" }, { signal: controller.signal });
		if (destination.master !== true || destination.settled !== true || destination.electionPending === true ||
			destination.localId !== status.masterId || destination.masterId !== status.masterId) return false;
		location.replace(target);
		return true;
	} catch {
		return false;
	} finally {
		clearTimeout(timeout);
	}
}
